const D = { density: .5, energy: .7, speed: 1, mult: 2, scale: 1, hue: 210, x: .5, y: .5, style: 'caustic', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// full-canvas additive render buffer, cached on size
if (!S.g || S.key !== width + 'x' + height) {
  S.g = createGraphics(width, height);
  S.g.pixelDensity(1);
  S.g.colorMode(HSB, 360, 100, 100, 100);
  S.key = width + 'x' + height;
}
// seed-dependent structure (hue offset / gradient span / phase)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1) * 90;
  S.spread = 110 + fr(2) * 170;
  S.phase = fr(3) * 6.2831853;
}

const TAU = 6.2831853;
const u = Math.min(width, height);
const R = u * 0.40 * P.scale;
const cx = P.x * width, cy = P.y * height;
const N = Math.round(40 + P.density * 520);
// continuous multiplier sweep — k grows forever on K.t so the envelope never repeats
const k = P.mult + K.t * (0.04 + P.speed * 0.12);
const rot = S.phase + K.t * 0.025 + K.section * 0.3 + A.mid * 0.3;
const expo = 0.4 + P.energy * 0.95 + K.intensity * 0.22 + A.bass * 0.5 + K.pulse * 0.15;
const style = P.style;
const hueBase = (P.hue + K.section * 17 + S.hoff + 720) % 360;

const coreA = Math.min(30, 9 + expo * 13 + A.treble * 8);
const haloA = Math.min(16, 4 + expo * 7);
const coreB = Math.min(100, 55 + expo * 45);
const haloB = coreB * 0.55;
const haloW = 1.4 + P.scale * 0.9 + A.rms * 1.2;
const coreW = 0.8 + P.scale * 0.2;

const g = S.g;
g.push();
g.clear();
g.blendMode(ADD);
g.noFill();
for (let i = 0; i < N; i++) {
  const u01 = i / N;
  const a1 = rot + TAU * u01;
  const a2 = rot + TAU * ((i * k) / N);
  const x1 = cx + R * Math.cos(a1), y1 = cy + R * Math.sin(a1);
  const x2 = cx + R * Math.cos(a2), y2 = cy + R * Math.sin(a2);
  let h, s;
  if (style === 'neon') { h = (hueBase + u01 * 300) % 360; s = 100; }
  else if (style === 'gold') { h = (38 + Math.sin(u01 * TAU + S.phase) * 11 + 360) % 360; s = 70; }
  else if (style === 'blueprint') { h = 200; s = 14; }
  else if (style === 'ink') { h = 0; s = 0; }
  else { h = (hueBase + u01 * S.spread) % 360; s = 84; } // caustic default
  // halo pass (wide, soft)
  g.strokeWeight(haloW);
  g.stroke(h, s * 0.8, haloB, haloA);
  g.line(x1, y1, x2, y2);
  // core pass (thin, bright)
  g.strokeWeight(coreW);
  g.stroke(h, s, coreB, coreA);
  g.line(x1, y1, x2, y2);
}
g.pop();

// ground tone per style (fills the whole frame for opaque genart bg)
let gh, gs, gb;
if (style === 'blueprint') { gh = 208; gs = 70; gb = 17; }
else if (style === 'ink') { gh = 0; gs = 0; gb = 5; }
else if (style === 'gold') { gh = 34; gs = 52; gb = 6; }
else { gh = hueBase; gs = 45; gb = 7; }

push();
if (P.alpha >= 100) {
  background(gh, gs, gb);
  image(g, 0, 0);
} else {
  tint(0, 0, 100, P.alpha);
  image(g, 0, 0);
  noTint();
}
pop();
